for df in [1.414, 0.765, 1.848, 1.932, 0.518]:
    add('chr', f'For a Sallen-Key stage, what R1/R2 gives a damping factor of {df}? (DF = 2 − R1/R2)', f'Với tầng Sallen-Key, tỉ số R1/R2 nào cho hệ số tắt dần {df}? (DF = 2 − R1/R2)', g(2 - df, 3), [g(df / 2, 3), g(2 + df, 3), g(1 / df, 3), g(df - 1, 3)], f'R1/R2 = 2 − DF = 2 − {df} = {g(2-df,3)}.', f'R1/R2 = 2 − DF = 2 − {df} = {g(2-df,3)}.', S('Floyd Problem 13', 'Floyd Bài 13'), 2)
for r1, r2 in [(1.0, 1.0), (5.6, 10), (680, 1000), (1.2, 1.0), (68, 100)]:
    df = 2 - r1 / r2
    add('chr', f'A Sallen-Key stage has R1 = {r1} kΩ and R2 = {r2} kΩ. What is the damping factor?', f'Tầng Sallen-Key có R1 = {r1} kΩ và R2 = {r2} kΩ. Hệ số tắt dần là bao nhiêu?', g(df, 3), [g(r1 / r2, 3), g(2 + r1 / r2, 3), g(1 + r1 / r2, 3), g(r2 / r1, 3)], f'DF = 2 − R1/R2 = 2 − {g(r1/r2,3)} = {g(df,3)}.', f'DF = 2 − R1/R2 = 2 − {g(r1/r2,3)} = {g(df,3)}.', S('Floyd Problem 7', 'Floyd Bài 7'), 2)
for r1, r2, r3, c, lab in [(47, 150, 1.8, 0.022, 'a'), (68, 180, 2.7, 0.01, 'b'), (10, 100, 1.0, 0.01, 'c'), (22, 220, 2.2, 0.047, 'd')]:
    f0 = 1 / (2 * math.pi * c * 1e-6) * math.sqrt((r1 + r3) / (r1 * r2 * r3 * 1e3 * 1e3 * 1e3 / 1e3 / 1e3 * 1)) if False else 1 / (2 * math.pi * c * 1e-6) * math.sqrt((r1 + r3) * 1e3 / (r1 * 1e3 * r2 * 1e3 * r3 * 1e3)); bw = 1 / (math.pi * r2 * 1e3 * c * 1e-6)
    add('bp', f'A multiple-feedback band-pass filter has R1 = {r1} kΩ, R2 = {r2} kΩ, R3 = {r3} kΩ and C1 = C2 = {c} μF. What is its bandwidth? (BW = 1/(π·R2·C))', f'Bộ lọc thông dải hồi tiếp nhiều đường có R1 = {r1} kΩ, R2 = {r2} kΩ, R3 = {r3} kΩ và C1 = C2 = {c} μF. Băng thông là bao nhiêu? (BW = 1/(π·R2·C))', hz(bw), [hz(bw * 2), hz(bw / 2), hz(f0), hz(1 / (2 * math.pi * r2 * 1e3 * c * 1e-6))], f'BW = 1/(π × {r2} kΩ × {c} μF) = {hz(bw)}.', f'BW = 1/(π × {r2} kΩ × {c} μF) = {hz(bw)}.', S('Floyd Problem 19', 'Floyd Bài 19'), 3)
    add('bp', f'A multiple-feedback band-pass filter has R1 = {r1} kΩ, R2 = {r2} kΩ, R3 = {r3} kΩ and C1 = C2 = {c} μF. What is its center frequency? (f0 = (1/2πC)√((R1+R3)/(R1·R2·R3)))', f'Bộ lọc thông dải hồi tiếp nhiều đường có R1 = {r1} kΩ, R2 = {r2} kΩ, R3 = {r3} kΩ và C1 = C2 = {c} μF. Tần số trung tâm là bao nhiêu? (f0 = (1/2πC)√((R1+R3)/(R1·R2·R3)))', hz(f0), [hz(f0 * 2), hz(f0 / 2), hz(bw), hz(f0 * math.pi)], f'f0 = {hz(f0)}; with BW = {hz(bw)} the Q is {g(f0/bw,3)}.', f'f0 = {hz(f0)}; với BW = {hz(bw)} thì Q = {g(f0/bw,3)}.', S('Floyd Problem 19', 'Floyd Bài 19'), 3)
for fl, fh in [(500, 5e3), (100, 10e3), (1e3, 3e3)]:
    add('bp', f'A high-pass filter (fc = {hz(fl)}) is cascaded with a low-pass filter (fc = {hz(fh)}). What is the bandwidth of the combined band-pass filter?', f'Bộ lọc thông cao (fc = {hz(fl)}) ghép nối tiếp với bộ lọc thông thấp (fc = {hz(fh)}). Băng thông của bộ lọc thông dải tổng hợp là bao nhiêu?', hz(fh - fl), [hz(fh + fl), hz(fh), hz(fl), hz(math.sqrt(fh * fl))], f'BW = f(LP) − f(HP) = {hz(fh)} − {hz(fl)} = {hz(fh-fl)}.', f'BW = f(LP) − f(HP) = {hz(fh)} − {hz(fl)} = {hz(fh-fl)}.', S('Floyd Self-Test Q14', 'Floyd Self-Test câu 14'), 2)
C = [('basic','A filter that passes dc and low frequencies and attenuates high frequencies is a','Bộ lọc cho qua một chiều và tần số thấp, làm suy giảm tần số cao là',('low-pass filter','bộ lọc thông thấp'),[('high-pass filter','bộ lọc thông cao'),('band-pass filter','bộ lọc thông dải'),('band-stop filter','bộ lọc chắn dải')],'Definition of a low-pass response.','Định nghĩa đáp ứng thông thấp.'),
 ('basic','Active filters are preferred over passive RC filters mainly because they','Bộ lọc tích cực được ưa chuộng hơn bộ lọc RC thụ động chủ yếu vì chúng',('can give gain and do not load the source','có thể cho độ lợi và không làm tải nguồn'),[('need no power supply','không cần nguồn cấp'),('work at any power level','làm việc ở mọi mức công suất'),('have no op-amp','không dùng op-amp')],'The op-amp provides gain and a high input / low output impedance.','Op-amp tạo độ lợi và trở kháng vào cao, ra thấp.'),
 ('chr','Compared with Butterworth, a Chebyshev response has','So với Butterworth, đáp ứng Chebyshev có',('a steeper roll-off but passband ripple','độ suy giảm dốc hơn nhưng có gợn trong dải thông'),[('a flatter passband','dải thông phẳng hơn'),('a slower roll-off','độ suy giảm chậm hơn'),('linear phase','pha tuyến tính')],'The faster transition is paid for with ripple.','Chuyển tiếp nhanh hơn phải trả bằng gợn.'),
 ('chr','The filter characteristic with the best (most linear) phase response is','Đặc tính bộ lọc có đáp ứng pha tốt nhất (tuyến tính nhất) là',('Bessel','Bessel'),[('Butterworth','Butterworth'),('Chebyshev','Chebyshev'),('Colpitts','Colpitts')],'Bessel gives constant delay and preserves pulse shapes.','Bessel cho trễ không đổi và giữ nguyên dạng xung.'),
 ('chr','A higher damping factor means the response is','Hệ số tắt dần cao hơn nghĩa là đáp ứng',('more heavily damped (less peaking)','bị tắt dần mạnh hơn (ít đỉnh nhô)'),[('more peaked near fc','có đỉnh nhô nhiều hơn gần fc'),('unrelated to the shape','không liên quan đến hình dạng'),('a pure oscillation','là dao động thuần')],'DF = 2 − R1/R2: larger DF means less feedback peaking.','DF = 2 − R1/R2: DF lớn nghĩa là ít nhô do hồi tiếp.'),
 ('lp','A two-pole Sallen-Key low-pass filter gives a roll-off of','Bộ lọc thông thấp Sallen-Key hai cực cho độ suy giảm',('−40 dB/decade','−40 dB/decade'),[('−20 dB/decade','−20 dB/decade'),('−60 dB/decade','−60 dB/decade'),('−80 dB/decade','−80 dB/decade')],'Two poles × −20 dB/decade.','Hai cực × −20 dB/decade.'),
 ('lp','To get a −60 dB/decade low-pass filter, one can cascade','Để có bộ lọc thông thấp −60 dB/decade có thể ghép nối tiếp',('a two-pole and a one-pole stage','một tầng hai cực và một tầng một cực'),[('two two-pole stages','hai tầng hai cực'),('three two-pole stages','ba tầng hai cực'),('one one-pole stage','một tầng một cực')],'2 + 1 = 3 poles = −60 dB/decade.','2 + 1 = 3 cực = −60 dB/decade.'),
 ('hp','A high-pass filter can be obtained from a low-pass Sallen-Key design by','Có thể thu được bộ lọc thông cao từ thiết kế Sallen-Key thông thấp bằng cách',('exchanging the positions of resistors and capacitors','đổi vị trí điện trở và tụ điện'),[('removing the op-amp','bỏ op-amp'),('doubling the supply','tăng gấp đôi nguồn'),('adding an inductor','thêm cuộn cảm')],'Floyd Problem 15: swap R and C in the frequency-selective network.','Floyd Bài 15: đổi R và C trong mạng chọn tần.'),
 ('bp','The multiple-feedback filter in Floyd is a','Bộ lọc hồi tiếp nhiều đường trong Floyd là',('band-pass filter','bộ lọc thông dải'),[('low-pass filter','bộ lọc thông thấp'),('high-pass filter','bộ lọc thông cao'),('notch filter','bộ lọc notch')],'It is the single-op-amp, two-capacitor band-pass design.','Đó là thiết kế thông dải một op-amp, hai tụ.'),
 ('bp','A notch filter is another name for a','Bộ lọc notch còn gọi là',('band-stop filter','bộ lọc chắn dải'),[('band-pass filter','bộ lọc thông dải'),('low-pass filter','bộ lọc thông thấp'),('all-pass filter','bộ lọc thông tất cả')],'It rejects a narrow band around f0.','Nó loại bỏ một dải hẹp quanh f0.'),
 ('bp','A band-stop filter can be built by summing the outputs of','Có thể làm bộ lọc chắn dải bằng cách cộng các ngõ ra của',('a low-pass and a high-pass filter whose critical frequencies are separated','một bộ lọc thông thấp và một bộ lọc thông cao có tần số tới hạn tách rời nhau'),[('two identical low-pass filters','hai bộ lọc thông thấp giống nhau'),('two integrators','hai mạch tích phân'),('two comparators','hai mạch so sánh')],'Floyd Problem 21: sum the low-pass and high-pass outputs.','Floyd Bài 21: cộng ngõ ra thông thấp và thông cao.'),
 ('bp','The state-variable filter can supply simultaneously','Bộ lọc biến trạng thái có thể cung cấp đồng thời',('low-pass, high-pass and band-pass outputs','ngõ ra thông thấp, thông cao và thông dải'),[('only a low-pass output','chỉ ngõ ra thông thấp'),('only a notch output','chỉ ngõ ra notch'),('a square-wave output','ngõ ra sóng vuông')],'The first integrator gives the band-pass, the second the low-pass, the summer the high-pass.','Tầng tích phân thứ nhất cho thông dải, thứ hai cho thông thấp, tầng cộng cho thông cao.')]
